        'versiculos' => [
            // Fuera de horario (plan 1.4e, D5): descanso y paz.
            ['fuera-versiculo-ex33-14-es', 'Y él dijo: Mi presencia irá contigo, y te daré descanso.', 'fuente' => 'Éxodo 33:14 (RVR1960)', 'fuera' => 'cualquiera'],
            ['versiculo-pr16-3-es', 'Encomienda a Jehová tus obras, Y tus pensamientos serán afirmados.', 'fuente' => 'Proverbios 16:3 (RVR1960)'],
            ['versiculo-sal118-24-es', 'Este es el día que hizo Jehová; Nos gozaremos y alegraremos en él.', 'fuente' => 'Salmos 118:24 (RVR1960)', 'momento' => 'manana'],
            ['versiculo-lm3-22-es', 'Por la misericordia de Jehová no hemos sido consumidos, porque nunca decayeron sus misericordias. Nuevas son cada mañana; grande es tu fidelidad.', 'fuente' => 'Lamentaciones 3:22-23 (RVR1960)', 'momento' => 'manana'],
            ['versiculo-sal4-8-es', 'En paz me acostaré, y asimismo dormiré; Porque solo tú, Jehová, me haces vivir confiado.', 'fuente' => 'Salmos 4:8 (RVR1960)', 'momento' => 'noche'],
            ['versiculo-jos1-9-es', 'Mira que te mando que te esfuerces y seas valiente; no temas ni desmayes, porque Jehová tu Dios estará contigo en dondequiera que vayas.', 'fuente' => 'Josué 1:9 (RVR1960)', 'dia_semana' => 1],
            ['versiculo-lc2-11-es', 'que os ha nacido hoy, en la ciudad de David, un Salvador, que es CRISTO el Señor.', 'fuente' => 'Lucas 2:11 (RVR1960)', 'ocasion' => 'navidad'],
            ['versiculo-mt28-6-es', 'No está aquí, pues ha resucitado, como dijo. Venid, ved el lugar donde fue puesto el Señor.', 'fuente' => 'Mateo 28:6 (RVR1960)', 'ocasion' => 'semana_santa'],
            ['versiculo-ps118-24-en', 'This is the day which the LORD hath made; we will rejoice and be glad in it.', 'idioma' => 'en', 'fuente' => 'Psalm 118:24 (KJV)'],
            ['versiculo-pr16-3-en', 'Commit thy works unto the LORD, and thy thoughts shall be established.', 'idioma' => 'en', 'fuente' => 'Proverbs 16:3 (KJV)'],
            ['versiculo-lk2-11-en', 'For unto you is born this day in the city of David a Saviour, which is Christ the Lord.', 'idioma' => 'en', 'fuente' => 'Luke 2:11 (KJV)', 'ocasion' => 'navidad'],
            ['versiculo-pr16-3-fr', "Recommande à l'Éternel tes oeuvres, Et tes projets réussiront.", 'idioma' => 'fr', 'fuente' => 'Proverbes 16:3 (LSG)'],
            ['versiculo-lm3-23-fr', 'Elles se renouvellent chaque matin. Oh! que ta fidélité est grande!', 'idioma' => 'fr', 'fuente' => 'Lamentations 3:23 (LSG)', 'momento' => 'manana'],
            // Segunda tanda, cotejada el 2026-10-19 en BibleGateway.
            ['versiculo-pr21-5-es', 'Los pensamientos del diligente ciertamente tienden a la abundancia; Mas todo el que se apresura alocadamente, de cierto va a la pobreza.', 'fuente' => 'Proverbios 21:5 (RVR1960)'],
            ['versiculo-pr22-1-es', 'De más estima es el buen nombre que las muchas riquezas, Y la buena fama más que la plata y el oro.', 'fuente' => 'Proverbios 22:1 (RVR1960)'],
            ['versiculo-pr15-1-es', 'La blanda respuesta quita la ira; Mas la palabra áspera hace subir el furor.', 'fuente' => 'Proverbios 15:1 (RVR1960)'],
            ['versiculo-ec3-1-es', 'Todo tiene su tiempo, y todo lo que se quiere debajo del cielo tiene su hora.', 'fuente' => 'Eclesiastés 3:1 (RVR1960)'],
            ['versiculo-ec4-9-es', 'Mejores son dos que uno; porque tienen mejor paga de su trabajo.', 'fuente' => 'Eclesiastés 4:9 (RVR1960)'],
            ['versiculo-flp4-13-es', 'Todo lo puedo en Cristo que me fortalece.', 'fuente' => 'Filipenses 4:13 (RVR1960)'],
            ['versiculo-ga6-9-es', 'No nos cansemos, pues, de hacer bien; porque a su tiempo segaremos, si no desmayamos.', 'fuente' => 'Gálatas 6:9 (RVR1960)'],
            ['versiculo-1co16-14-es', 'Todas vuestras cosas sean hechas con amor.', 'fuente' => '1 Corintios 16:14 (RVR1960)'],
            ['versiculo-sal90-17-es', 'Sea la luz de Jehová nuestro Dios sobre nosotros, Y la obra de nuestras manos confirma sobre nosotros; Sí, la obra de nuestras manos confirma.', 'fuente' => 'Salmos 90:17 (RVR1960)'],
            ['versiculo-sal5-3-es', 'Oh Jehová, de mañana oirás mi voz; De mañana me presentaré delante de ti, y esperaré.', 'fuente' => 'Salmos 5:3 (RVR1960)', 'momento' => 'manana'],
            ['versiculo-lc2-14-es', '¡Gloria a Dios en las alturas, Y en la tierra paz, buena voluntad para con los hombres!', 'fuente' => 'Lucas 2:14 (RVR1960)', 'ocasion' => 'navidad'],
            ['versiculo-jn11-25-es', 'Le dijo Jesús: Yo soy la resurrección y la vida; el que cree en mí, aunque esté muerto, vivirá.', 'fuente' => 'Juan 11:25 (RVR1960)', 'ocasion' => 'semana_santa'],
            ['versiculo-sal65-11-es', 'Tú coronas el año con tus bienes, Y tus nubes destilan grosura.', 'fuente' => 'Salmos 65:11 (RVR1960)', 'ocasion' => 'anio_nuevo'],
            ['versiculo-nm6-24-es', 'Jehová te bendiga, y te guarde; Jehová haga resplandecer su rostro sobre ti, y tenga de ti misericordia; Jehová alce sobre ti su rostro, y ponga en ti paz.', 'fuente' => 'Números 6:24-26 (RVR1960)', 'ocasion' => 'cumpleanos'],
            ['versiculo-pr31-25-es', 'Fuerza y honor son su vestidura; Y se ríe de lo por venir.', 'fuente' => 'Proverbios 31:25 (RVR1960)', 'ocasion' => 'dia_madre'],
            ['versiculo-pr20-7-es', 'Camina en su integridad el justo; Sus hijos son dichosos después de él.', 'fuente' => 'Proverbios 20:7 (RVR1960)', 'ocasion' => 'dia_padre'],
            ['versiculo-sal33-12-es', 'Bienaventurada la nación cuyo Dios es Jehová, El pueblo que él escogió como heredad para sí.', 'fuente' => 'Salmos 33:12 (RVR1960)', 'ocasion' => 'fiestas_patrias'],
            // Tercera tanda, cotejada el 2026-10-21 en BibleGateway (pedido del desarrollador: más versículos).
            ['versiculo-col3-23-es', 'Y todo lo que hagáis, hacedlo de corazón, como para el Señor y no para los hombres;', 'fuente' => 'Colosenses 3:23 (RVR1960)'],
            ['versiculo-pr3-5-es', 'Fíate de Jehová de todo tu corazón, Y no te apoyes en tu propia prudencia. Reconócelo en todos tus caminos, Y él enderezará tus veredas.', 'fuente' => 'Proverbios 3:5-6 (RVR1960)'],
            ['versiculo-is41-10-es', 'No temas, porque yo estoy contigo; no desmayes, porque yo soy tu Dios que te esfuerzo; siempre te ayudaré, siempre te sustentaré con la diestra de mi justicia.', 'fuente' => 'Isaías 41:10 (RVR1960)'],
            ['versiculo-sal23-1-es', 'Jehová es mi pastor; nada me faltará.', 'fuente' => 'Salmos 23:1 (RVR1960)'],
            ['versiculo-sal46-1-es', 'Dios es nuestro amparo y fortaleza, Nuestro pronto auxilio en las tribulaciones.', 'fuente' => 'Salmos 46:1 (RVR1960)'],
            ['versiculo-sal121-1-es', 'Alzaré mis ojos a los montes; ¿De dónde vendrá mi socorro? Mi socorro viene de Jehová, Que hizo los cielos y la tierra.', 'fuente' => 'Salmos 121:1-2 (RVR1960)'],
            ['versiculo-sal37-5-es', 'Encomienda a Jehová tu camino, Y confía en él; y él hará.', 'fuente' => 'Salmos 37:5 (RVR1960)'],
            ['versiculo-ro8-28-es', 'Y sabemos que a los que aman a Dios, todas las cosas les ayudan a bien, esto es, a los que conforme a su propósito son llamados.', 'fuente' => 'Romanos 8:28 (RVR1960)'],
            ['versiculo-ro12-12-es', 'gozosos en la esperanza; sufridos en la tribulación; constantes en la oración;', 'fuente' => 'Romanos 12:12 (RVR1960)'],
            ['versiculo-flp4-6-es', 'Por nada estéis afanosos, sino sean conocidas vuestras peticiones delante de Dios en toda oración y ruego, con acción de gracias.', 'fuente' => 'Filipenses 4:6 (RVR1960)'],
            ['versiculo-stg1-5-es', 'Y si alguno de vosotros tiene falta de sabiduría, pídala a Dios, el cual da a todos abundantemente y sin reproche, y le será dada.', 'fuente' => 'Santiago 1:5 (RVR1960)'],
            ['versiculo-1p5-7-es', 'echando toda vuestra ansiedad sobre él, porque él tiene cuidado de vosotros.', 'fuente' => '1 Pedro 5:7 (RVR1960)'],
            ['versiculo-pr12-24-es', 'La mano de los diligentes señoreará; Mas la negligencia será tributaria.', 'fuente' => 'Proverbios 12:24 (RVR1960)'],
            ['versiculo-pr14-23-es', 'En toda labor hay fruto; Mas las vanas palabras de los labios empobrecen.', 'fuente' => 'Proverbios 14:23 (RVR1960)'],
            ['versiculo-pr16-9-es', 'El corazón del hombre piensa su camino; Mas Jehová endereza sus pasos.', 'fuente' => 'Proverbios 16:9 (RVR1960)'],
            ['versiculo-pr27-17-es', 'Hierro con hierro se aguza; Y así el hombre aguza el rostro de su amigo.', 'fuente' => 'Proverbios 27:17 (RVR1960)'],
            ['versiculo-pr11-14-es', 'Donde no hay dirección sabia, caerá el pueblo; Mas en la multitud de consejeros hay seguridad.', 'fuente' => 'Proverbios 11:14 (RVR1960)'],
            ['versiculo-pr4-23-es', 'Sobre toda cosa guardada, guarda tu corazón; Porque de él mana la vida.', 'fuente' => 'Proverbios 4:23 (RVR1960)'],
            ['versiculo-lc16-10-es', 'El que es fiel en lo muy poco, también en lo más es fiel; y el que en lo muy poco es injusto, también en lo más es injusto.', 'fuente' => 'Lucas 16:10 (RVR1960)', 'area' => 'erp'],
            ['versiculo-sal127-1-es', 'Si Jehová no edificare la casa, En vano trabajan los que la edifican; Si Jehová no guardare la ciudad, En vano vela la guardia.', 'fuente' => 'Salmos 127:1 (RVR1960)'],
            ['versiculo-is40-31-es', 'pero los que esperan a Jehová tendrán nuevas fuerzas; levantarán alas como las águilas; correrán, y no se cansarán; caminarán, y no se fatigarán.', 'fuente' => 'Isaías 40:31 (RVR1960)'],
            ['versiculo-jn14-27-es', 'La paz os dejo, mi paz os doy; yo no os la doy como el mundo la da. No se turbe vuestro corazón, ni tenga miedo.', 'fuente' => 'Juan 14:27 (RVR1960)'],
            ['versiculo-he13-8-es', 'Jesucristo es el mismo ayer, y hoy, y por los siglos.', 'fuente' => 'Hebreos 13:8 (RVR1960)'],
            ['versiculo-mi6-8-es', 'Oh hombre, él te ha declarado lo que es bueno, y qué pide Jehová de ti: solamente hacer justicia, y amar misericordia, y humillarte ante tu Dios.', 'fuente' => 'Miqueas 6:8 (RVR1960)'],
            ['versiculo-sal119-105-es', 'Lámpara es a mis pies tu palabra, Y lumbrera a mi camino.', 'fuente' => 'Salmos 119:105 (RVR1960)'],
            ['versiculo-sal143-8-es', 'Hazme oír por la mañana tu misericordia, Porque en ti he confiado; Hazme saber el camino por donde ande, Porque a ti he elevado mi alma.', 'fuente' => 'Salmos 143:8 (RVR1960)', 'momento' => 'manana'],
            ['versiculo-sal3-5-es', 'Yo me acosté y dormí, Y desperté, porque Jehová me sustentaba.', 'fuente' => 'Salmos 3:5 (RVR1960)', 'momento' => 'manana'],
            ['versiculo-mt11-28-es', 'Venid a mí todos los que estáis trabajados y cargados, y yo os haré descansar.', 'fuente' => 'Mateo 11:28 (RVR1960)', 'momento' => 'tarde'],
            ['versiculo-flp4-7-es', 'Y la paz de Dios, que sobrepasa todo entendimiento, guardará vuestros corazones y vuestros pensamientos en Cristo Jesús.', 'fuente' => 'Filipenses 4:7 (RVR1960)', 'momento' => 'noche'],
            ['versiculo-mt6-34-es', 'Así que, no os afanéis por el día de mañana, porque el día de mañana traerá su afán. Basta a cada día su propio mal.', 'fuente' => 'Mateo 6:34 (RVR1960)', 'momento' => 'noche'],
            ['versiculo-sal122-1-es', 'Yo me alegré con los que me decían: A la casa de Jehová iremos.', 'fuente' => 'Salmos 122:1 (RVR1960)', 'dia_semana' => 7],
            ['versiculo-is9-6-es', 'Porque un niño nos es nacido, hijo nos es dado, y el principado sobre su hombro; y se llamará su nombre Admirable, Consejero, Dios Fuerte, Padre Eterno, Príncipe de Paz.', 'fuente' => 'Isaías 9:6 (RVR1960)', 'ocasion' => 'navidad'],
            ['versiculo-jn3-16-es', 'Porque de tal manera amó Dios al mundo, que ha dado a su Hijo unigénito, para que todo aquel que en él cree, no se pierda, mas tenga vida eterna.', 'fuente' => 'Juan 3:16 (RVR1960)', 'ocasion' => 'semana_santa'],
            ['versiculo-is43-19-es', 'He aquí que yo hago cosa nueva; pronto saldrá a luz; ¿no la conoceréis? Otra vez abriré camino en el desierto, y ríos en la soledad.', 'fuente' => 'Isaías 43:19 (RVR1960)', 'ocasion' => 'anio_nuevo'],
            ['versiculo-2co5-17-es', 'De modo que si alguno está en Cristo, nueva criatura es; las cosas viejas pasaron; he aquí todas son hechas nuevas.', 'fuente' => '2 Corintios 5:17 (RVR1960)', 'ocasion' => 'anio_nuevo'],
            ['versiculo-sal90-12-es', 'Enséñanos de tal modo a contar nuestros días, Que traigamos al corazón sabiduría.', 'fuente' => 'Salmos 90:12 (RVR1960)', 'ocasion' => 'cumpleanos'],
            ['versiculo-ex20-12-es', 'Honra a tu padre y a tu madre, para que tus días se alarguen en la tierra que Jehová tu Dios te da.', 'fuente' => 'Éxodo 20:12 (RVR1960)', 'ocasion' => 'dia_padre'],
            ['versiculo-pr14-34-es', 'La justicia engrandece a la nación; Mas el pecado es afrenta de las naciones.', 'fuente' => 'Proverbios 14:34 (RVR1960)', 'ocasion' => 'fiestas_patrias'],
            ['versiculo-1s7-12-es', 'Tomó luego Samuel una piedra y la puso entre Mizpa y Sen, y le puso por nombre Eben-ezer, diciendo: Hasta aquí nos ayudó Jehová.', 'fuente' => '1 Samuel 7:12 (RVR1960)', 'ocasion' => 'aniversario'],
            ['versiculo-sal103-2-es', 'Bendice, alma mía, a Jehová, Y no olvides ninguno de sus beneficios.', 'fuente' => 'Salmos 103:2 (RVR1960)', 'ocasion' => 'aniversario'],
            ['versiculo-ga6-9-en', 'And let us not be weary in well doing: for in due season we shall reap, if we faint not.', 'idioma' => 'en', 'fuente' => 'Galatians 6:9 (KJV)'],
            ['versiculo-php4-13-en', 'I can do all things through Christ which strengtheneth me.', 'idioma' => 'en', 'fuente' => 'Philippians 4:13 (KJV)'],
            ['versiculo-lk2-14-en', 'Glory to God in the highest, and on earth peace, good will toward men.', 'idioma' => 'en', 'fuente' => 'Luke 2:14 (KJV)', 'ocasion' => 'navidad'],
            ['versiculo-ps65-11-en', 'Thou crownest the year with thy goodness; and thy paths drop fatness.', 'idioma' => 'en', 'fuente' => 'Psalm 65:11 (KJV)', 'ocasion' => 'anio_nuevo'],
            ['versiculo-nm6-24-en', 'The LORD bless thee, and keep thee: The LORD make his face shine upon thee, and be gracious unto thee: The LORD lift up his countenance upon thee, and give thee peace.', 'idioma' => 'en', 'fuente' => 'Numbers 6:24-26 (KJV)', 'ocasion' => 'cumpleanos'],
            ['versiculo-ga6-9-fr', 'Ne nous lassons pas de faire le bien; car nous moissonnerons au temps convenable, si nous ne nous relâchons pas.', 'idioma' => 'fr', 'fuente' => 'Galates 6:9 (LSG)'],
            ['versiculo-ph4-13-fr', 'Je puis tout par celui qui me fortifie.', 'idioma' => 'fr', 'fuente' => 'Philippiens 4:13 (LSG)'],
            ['versiculo-lc2-14-fr', "Gloire à Dieu dans les lieux très hauts, Et paix sur la terre parmi les hommes qu'il agrée!", 'idioma' => 'fr', 'fuente' => 'Luc 2:14 (LSG)', 'ocasion' => 'navidad'],
            ['versiculo-nb6-24-fr', "Que l'Éternel te bénisse, et qu'il te garde! Que l'Éternel fasse luire sa face sur toi, et qu'il t'accorde sa grâce! Que l'Éternel tourne sa face vers toi, et qu'il te donne la paix!", 'idioma' => 'fr', 'fuente' => 'Nombres 6:24-26 (LSG)', 'ocasion' => 'cumpleanos'],
            // Portugués (Bíblia Portuguesa Mundial) y alemán (Lutherbibel 1912), de dominio público, cotejados el 2026-11-09
            // en ebible.org (plan 1.4aa, paso 7). Lutero numera los salmos con el título: Psalm 4,9 y 65,12 son 4:8 y 65:11
            // en las otras versiones. De la BPM se quitan solo las comillas que abren o cierran en otro versículo.
            ['fuera-versiculo-ex33-14-pt', 'Ele disse: “A minha presença irá com você, e eu lhe darei descanso.”', 'idioma' => 'pt', 'fuente' => 'Êxodo 33:14 (BPM)', 'fuera' => 'cualquiera'],
            ['versiculo-pr16-3-pt', 'Consagre ao SENHOR tudo o que você faz, e os seus planos serão bem-sucedidos.', 'idioma' => 'pt', 'fuente' => 'Provérbios 16:3 (BPM)'],
            ['versiculo-sal118-24-pt', 'Este é o dia que o SENHOR fez. Vamos nos alegrar e exultar nele!', 'idioma' => 'pt', 'fuente' => 'Salmos 118:24 (BPM)', 'momento' => 'manana'],
            ['versiculo-lm3-22-pt', 'É por causa das bondades do SENHOR que não somos consumidos, porque as suas misericórdias não falham. Elas se renovam a cada manhã. Grande é a sua fidelidade.', 'idioma' => 'pt', 'fuente' => 'Lamentações 3:22-23 (BPM)', 'momento' => 'manana'],
            ['versiculo-sal4-8-pt', 'Em paz me deitarei e também dormirei, pois só tu, SENHOR, me fazes viver em segurança.', 'idioma' => 'pt', 'fuente' => 'Salmos 4:8 (BPM)', 'momento' => 'noche'],
            ['versiculo-jos1-9-pt', 'Eu não lhe ordenei? Seja forte e corajoso. Não tenha medo. Não se apavore, pois o SENHOR, seu Deus, está com você por onde quer que você andar.', 'idioma' => 'pt', 'fuente' => 'Josué 1:9 (BPM)', 'dia_semana' => 1],
            ['versiculo-lc2-11-pt', 'Pois hoje lhes nasceu, na cidade de Davi, um Salvador, que é Cristo o Senhor.', 'idioma' => 'pt', 'fuente' => 'Lucas 2:11 (BPM)', 'ocasion' => 'navidad'],
            ['versiculo-lc2-14-pt', '“Glória a Deus nas maiores alturas, e paz na terra, boa vontade para com os homens.”', 'idioma' => 'pt', 'fuente' => 'Lucas 2:14 (BPM)', 'ocasion' => 'navidad'],
            ['versiculo-mt28-6-pt', 'Ele não está aqui, pois ressuscitou, assim como ele disse. Venham, vejam o lugar onde o Senhor estava deitado.', 'idioma' => 'pt', 'fuente' => 'Mateus 28:6 (BPM)', 'ocasion' => 'semana_santa'],
            ['versiculo-jo3-16-pt', 'Porque Deus amou o mundo de tal maneira que deu o seu Filho unigênito, para que todo aquele que nele crê não pereça, mas tenha a vida eterna.', 'idioma' => 'pt', 'fuente' => 'João 3:16 (BPM)', 'ocasion' => 'semana_santa'],
            ['versiculo-sal65-11-pt', 'Tu coroas o ano com a tua fartura. As tuas carroças transbordam de abundância.', 'idioma' => 'pt', 'fuente' => 'Salmos 65:11 (BPM)', 'ocasion' => 'anio_nuevo'],
            ['versiculo-nm6-24-pt', '‘O SENHOR te abençoe e te guarde. O SENHOR faça resplandecer o seu rosto sobre ti, e tenha misericórdia de ti. O SENHOR levante o seu rosto sobre ti, e te dê a paz.’', 'idioma' => 'pt', 'fuente' => 'Números 6:24-26 (BPM)', 'ocasion' => 'cumpleanos'],
            ['versiculo-ga6-9-pt', 'Não nos cansemos de fazer o bem, pois no tempo devido colheremos, se não desistirmos.', 'idioma' => 'pt', 'fuente' => 'Gálatas 6:9 (BPM)'],
            ['versiculo-flp4-13-pt', 'Posso todas as coisas por meio de Cristo que me fortalece.', 'idioma' => 'pt', 'fuente' => 'Filipenses 4:13 (BPM)'],
            ['versiculo-sal23-1-pt', 'O SENHOR é o meu pastor; nada me faltará.', 'idioma' => 'pt', 'fuente' => 'Salmos 23:1 (BPM)'],
            ['versiculo-mt11-28-pt', 'Venham a mim, todos vocês que estão cansados e sobrecarregados, e eu lhes darei descanso.', 'idioma' => 'pt', 'fuente' => 'Mateus 11:28 (BPM)', 'momento' => 'tarde'],
            ['fuera-versiculo-ex33-14-de', 'Er sprach: Mein Angesicht soll vorangehen; damit will ich dich leiten.', 'idioma' => 'de', 'fuente' => '2. Mose 33,14 (Luther 1912)', 'fuera' => 'cualquiera'],
            ['versiculo-pr16-3-de', 'Befiehl dem HERRN deine Werke, so werden deine Anschläge fortgehen.', 'idioma' => 'de', 'fuente' => 'Sprüche 16,3 (Luther 1912)'],
            ['versiculo-ps118-24-de', 'Dies ist der Tag, den der HERR macht; lasset uns freuen und fröhlich darinnen sein.', 'idioma' => 'de', 'fuente' => 'Psalm 118,24 (Luther 1912)', 'momento' => 'manana'],
            ['versiculo-kl3-22-de', 'Die Güte des HERRN ist\'s, daß wir nicht gar aus sind; seine Barmherzigkeit hat noch kein Ende, sondern sie ist alle Morgen neu, und deine Treue ist groß.', 'idioma' => 'de', 'fuente' => 'Klagelieder 3,22-23 (Luther 1912)', 'momento' => 'manana'],
            ['versiculo-ps4-9-de', 'Ich liege und schlafe ganz mit Frieden; denn allein du, HERR, hilfst mir, daß ich sicher wohne.', 'idioma' => 'de', 'fuente' => 'Psalm 4,9 (Luther 1912)', 'momento' => 'noche'],
            ['versiculo-jos1-9-de', 'Siehe, ich habe dir geboten, daß du getrost und freudig seist. Laß dir nicht grauen und entsetze dich nicht; denn der HERR, dein Gott, ist mit dir in allem, was du tun wirst.', 'idioma' => 'de', 'fuente' => 'Josua 1,9 (Luther 1912)', 'dia_semana' => 1],
            ['versiculo-lk2-11-de', 'denn euch ist heute der Heiland geboren, welcher ist Christus, der HERR, in der Stadt Davids.', 'idioma' => 'de', 'fuente' => 'Lukas 2,11 (Luther 1912)', 'ocasion' => 'navidad'],
            ['versiculo-lk2-14-de', 'Ehre sei Gott in der Höhe und Frieden auf Erden und den Menschen ein Wohlgefallen.', 'idioma' => 'de', 'fuente' => 'Lukas 2,14 (Luther 1912)', 'ocasion' => 'navidad'],
            ['versiculo-mt28-6-de', 'Er ist nicht hier; er ist auferstanden, wie er gesagt hat. Kommt her und seht die Stätte, da der HERR gelegen hat.', 'idioma' => 'de', 'fuente' => 'Matthäus 28,6 (Luther 1912)', 'ocasion' => 'semana_santa'],
            ['versiculo-jh3-16-de', 'Also hat Gott die Welt geliebt, daß er seinen eingeborenen Sohn gab, auf daß alle, die an ihn glauben, nicht verloren werden, sondern das ewige Leben haben.', 'idioma' => 'de', 'fuente' => 'Johannes 3,16 (Luther 1912)', 'ocasion' => 'semana_santa'],
            ['versiculo-ps65-12-de', 'Du krönst das Jahr mit deinem Gut, und deine Fußtapfen triefen von Fett.', 'idioma' => 'de', 'fuente' => 'Psalm 65,12 (Luther 1912)', 'ocasion' => 'anio_nuevo'],
            ['versiculo-4mo6-24-de', 'Der HERR segne dich und behüte dich; der HERR lasse sein Angesicht leuchten über dir und sei dir gnädig; der HERR hebe sein Angesicht über dich und gebe dir Frieden.', 'idioma' => 'de', 'fuente' => '4. Mose 6,24-26 (Luther 1912)', 'ocasion' => 'cumpleanos'],
            ['versiculo-ga6-9-de', 'Lasset uns aber Gutes tun und nicht müde werden; denn zu seiner Zeit werden wir auch ernten ohne Aufhören.', 'idioma' => 'de', 'fuente' => 'Galater 6,9 (Luther 1912)'],
            ['versiculo-php4-13-de', 'Ich vermag alles durch den, der mich mächtig macht, Christus.', 'idioma' => 'de', 'fuente' => 'Philipper 4,13 (Luther 1912)'],
            ['versiculo-ps23-1-de', 'Der HERR ist mein Hirte; mir wird nichts mangeln.', 'idioma' => 'de', 'fuente' => 'Psalm 23,1 (Luther 1912)'],
            ['versiculo-mt11-28-de', 'Kommet her zu mir alle, die ihr mühselig und beladen seid; ich will euch erquicken.', 'idioma' => 'de', 'fuente' => 'Matthäus 11,28 (Luther 1912)', 'momento' => 'tarde'],
        ],
    ],

    // Plan 1.4b, D10: agradecimiento del aniversario en la barra superior, entre el logo y el buscador. Corto (hasta
    // 60 letras, lo exige la base) y con {anios}. Cada año sale uno, el mismo para todos.
    'agradecimientos' => [
        ['gracias-a01-es', 'Gracias a Dios por {anios} años de camino'],
        ['gracias-a02-es', '{anios} años: gracias a Dios por cada paso'],
        ['gracias-a03-es', 'Gracias, Señor, por {anios} años de bendición'],
        ['gracias-a04-es', 'Por {anios} años de fidelidad, gracias a Dios'],
        ['gracias-a05-es', '{anios} años de la mano de Dios'],
        ['gracias-a06-es', 'A Dios la gloria por {anios} años'],
        ['gracias-a07-es', 'Dios nos trajo hasta aquí: {anios} años'],
        ['gracias-a08-es', 'Gracias a Dios por {anios} años juntos'],
        ['gracias-a09-es', '{anios} años de bendiciones. ¡Gracias, Dios!'],
        ['gracias-a10-es', 'Agradecidos con Dios por {anios} años'],
        ['gracias-a11-es', '{anios} años construyendo con la ayuda de Dios'],
        ['gracias-a12-es', 'Hasta aquí nos ayudó Dios: {anios} años'],
    ],
];
